with flattened as (select id, host, log_ts, level, status_code, attr_key, value from app_logs lateral view explode(context) x as attr_key, value), flattened_attrs as (select id, level, status_code, attr_key, value, shiftright(status_code, 2) as status_code_high, cast((status_code & 1) != 0 as int) as has_fault from flattened), base as (select *, substring(level, 1, 2) as level_prefix, round(status_code * 1.07, 2) as adjusted_status_code, coalesce(attr_key, 'OTHER') as attr_key_clean from flattened_attrs where attr_key is not null), ranked as (select * from (select *, row_number() over (partition by level order by adjusted_status_code, id, attr_key) as dedup_rank from base) x where dedup_rank = 1) select id, level, status_code, attr_key, has_fault, adjusted_status_code, attr_key_clean from ranked order by adjusted_status_code desc
